(function () {
  "use strict";

  const LABEL = "[Algolia Engagement Tracker]";
  const DEBUG =
    new URLSearchParams(location.search).get("algoliaChatDebug") === "1" ||
    new URLSearchParams(location.search).get("algoliaEngagementDebug") === "1";

  const PROFILE_KEY = "algolia_profile";
  const SESSION_KEY = "algolia_session";
  const EVENTS_KEY = "algolia_events";
  const PROACTIVE_STATE_KEY = "algolia_proactive_state";
  const TOKEN_KEY = "algolia_token";
  const RESET_QUERY_PARAM = "algoliaProactiveReset";

  const PROFILE_SCHEMA = "AlgoliaEngagementProfile.v1";
  const SESSION_SCHEMA = "AlgoliaEngagementSession.v1";
  const EVENTS_SCHEMA = "AlgoliaEngagementEvents.v1";

  const SESSION_TTL_MS = 30 * 60 * 1000;
  const MAX_EVENTS = 100;
  const MAX_PAGES = 40;
  const MAX_ENGAGEMENTS = 20;
  const MAX_TEXT = 120;
  const DWELL_MILESTONES_MS = [5000, 10000];
  const SCROLL_MILESTONES = [50, 75, 100];
  const SAFE_UTM_KEYS = [
    "utm_source",
    "utm_medium",
    "utm_campaign",
    "utm_content",
    "utm_term",
  ];
  const REDACTED_PROP_PATTERN =
    /email|phone|password|passwd|token|secret|api[_-]?key|credential|name|company|value/i;

  let config = {};
  let consentAdapter = null;
  let session = null;
  let currentPageId = null;
  let currentPageStartedAt = Date.now();
  let currentScrollMilestone = 0;
  let routeWatchInstalled = false;
  let clickWatchInstalled = false;
  let formWatchInstalled = false;
  let searchWatchInstalled = false;
  let chatWatchInstalled = false;
  let explicitUserToken = null;

  function debug(...args) {
    if (DEBUG) console.log(LABEL, ...args);
  }

  function readWindowConfig() {
    try {
      const value = window.ALGOLIA_VISITOR_CONFIG;
      return value && typeof value === "object" ? value : {};
    } catch {
      return {};
    }
  }

  function configure(nextConfig) {
    config = { ...config, ...(nextConfig || {}) };
    debug("configured", config);
  }

  function isAllowed() {
    if (!consentAdapter) return true;
    try {
      return consentAdapter.isAllowed();
    } catch {
      return false;
    }
  }

  function setConsentAdapter(adapter) {
    consentAdapter = adapter;
    if (adapter && typeof adapter.onConsentChange === "function") {
      adapter.onConsentChange(() => {
        if (!isAllowed()) return;
        initializeState();
        track("consent_change", { allowed: true, source: "adapter" });
      });
    }
  }

  function readJson(storage, key, fallback) {
    try {
      const raw = storage.getItem(key);
      return raw ? JSON.parse(raw) : fallback;
    } catch {
      return fallback;
    }
  }

  function writeJson(storage, key, value) {
    if (!isAllowed()) return;
    try {
      if (value === null) storage.removeItem(key);
      else storage.setItem(key, JSON.stringify(value));
    } catch {
      // Storage can be unavailable in private modes; the tracker must not break the page.
    }
  }

  function readProfile() {
    return readJson(localStorage, PROFILE_KEY, null) || {
      schema: PROFILE_SCHEMA,
      visitorId: null,
      userToken: null,
      tokenSource: null,
      firstSeenAt: null,
      lastSeenAt: null,
      visits: 0,
      persona: null,
    };
  }

  function writeProfile(profile) {
    writeJson(localStorage, PROFILE_KEY, profile);
  }

  function readEventsEnvelope() {
    const fallback = { schema: EVENTS_SCHEMA, sessionId: null, events: [] };
    const value = readJson(sessionStorage, EVENTS_KEY, fallback);
    return {
      schema: value.schema || EVENTS_SCHEMA,
      sessionId: value.sessionId || session?.sessionId || null,
      events: Array.isArray(value.events) ? value.events : [],
    };
  }

  function writeEventsEnvelope(envelope) {
    writeJson(sessionStorage, EVENTS_KEY, {
      schema: EVENTS_SCHEMA,
      sessionId: envelope.sessionId || session?.sessionId || null,
      events: (envelope.events || []).slice(-MAX_EVENTS),
    });
  }

  function readSession() {
    return readJson(sessionStorage, SESSION_KEY, null);
  }

  function writeSession(nextSession) {
    session = {
      ...nextSession,
      schema: SESSION_SCHEMA,
      lastSeenAt: Date.now(),
    };
    writeJson(sessionStorage, SESSION_KEY, session);
  }

  function getCookie(name) {
    try {
      const entry = document.cookie
        .split(";")
        .find((part) => part.trim().startsWith(`${name}=`));
      return entry ? decodeURIComponent(entry.trim().slice(name.length + 1)) : null;
    } catch {
      return null;
    }
  }

  function id(prefix) {
    try {
      const array = new Uint8Array(12);
      crypto.getRandomValues(array);
      return `${prefix}_${Array.from(array, (byte) =>
        byte.toString(16).padStart(2, "0")
      ).join("")}`;
    } catch {
      return `${prefix}_${Math.random().toString(16).slice(2)}${Date.now().toString(16)}`;
    }
  }

  function getUserToken() {
    if (explicitUserToken) return { token: explicitUserToken, source: "override" };
    if (config.cookieName) {
      const token = getCookie(config.cookieName);
      if (token) return { token, source: "cookie" };
    }

    let token = null;
    try {
      token = sessionStorage.getItem(TOKEN_KEY);
      if (!token) {
        token = id("tok");
        sessionStorage.setItem(TOKEN_KEY, token);
      }
    } catch {
      token = id("tok");
    }
    return { token, source: "ephemeral" };
  }

  function nowIso() {
    return new Date().toISOString();
  }

  function truncate(value, maxLength = MAX_TEXT) {
    if (value === undefined || value === null) return undefined;
    const text = redactSensitiveText(String(value).replace(/\s+/g, " ").trim());
    if (!text) return undefined;
    return text.length > maxLength ? `${text.slice(0, maxLength - 1)}...` : text;
  }

  function redactSensitiveText(value) {
    return String(value)
      .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, "[redacted-email]")
      .replace(/\b(?:\+?\d[\d .()/-]{7,}\d)\b/g, "[redacted-phone]")
      .replace(/\b(?:sk|key|token|secret)[_-]?[A-Z0-9_-]{12,}\b/gi, "[redacted-secret]");
  }

  function safeUrl(value) {
    if (!value) return undefined;
    try {
      const url = new URL(value, location.origin);
      return `${url.origin}${url.pathname}`;
    } catch {
      return undefined;
    }
  }

  function safeHrefFromElement(element) {
    const href = element?.getAttribute?.("href") || element?.href;
    return safeUrl(href);
  }

  function currentUrl() {
    return safeUrl(location.href);
  }

  function currentUtm() {
    const search = new URLSearchParams(location.search || "");
    const utm = {};
    for (const key of SAFE_UTM_KEYS) {
      const value = truncate(search.get(key), 80);
      if (value) utm[key] = value;
    }
    return Object.keys(utm).length ? utm : undefined;
  }

  function sanitizeProps(props) {
    const clean = {};
    for (const [key, value] of Object.entries(props || {})) {
      if (REDACTED_PROP_PATTERN.test(key)) continue;
      if (value === undefined || value === null) continue;
      if (typeof value === "string") clean[key] = truncate(value);
      else if (typeof value === "number" || typeof value === "boolean") clean[key] = value;
      else if (Array.isArray(value)) clean[key] = value.slice(0, 10).map((item) => truncate(item));
      else if (typeof value === "object") clean[key] = sanitizeProps(value);
    }
    return clean;
  }

  function pageClassification(pathname = location.pathname) {
    const path = pathname.toLowerCase();
    const text = `${path} ${document.title || ""}`.toLowerCase();

    if (path === "/" || path === "") return { pageGroup: "home", topic: "homepage" };
    if (path.includes("/pricing")) return { pageGroup: "pricing", topic: "pricing" };
    if (path.includes("/demo") || path.includes("contact-sales")) {
      return { pageGroup: "conversion", topic: "demo_request" };
    }
    if (path.includes("/customers")) {
      return { pageGroup: "customer_story", topic: topicFromText(text, "customer_proof") };
    }
    if (path.includes("/doc/") || path.includes("/docs") || path.includes("/api")) {
      return { pageGroup: "documentation", topic: topicFromText(text, "implementation") };
    }
    if (path.includes("/developers") || path.includes("/developer")) {
      return { pageGroup: "developer", topic: topicFromText(text, "developer_experience") };
    }
    if (path.includes("/products")) {
      return {
        pageGroup: "product",
        topic: topicFromText(text, "product_research"),
        ...productFocusFromText(text),
      };
    }
    if (path.includes("/industries") || path.includes("/solutions")) {
      return { pageGroup: "solution", topic: topicFromText(text, "industry_solution") };
    }
    if (path.includes("/blog")) return { pageGroup: "blog", topic: topicFromText(text, "education") };
    if (path.includes("/resources")) {
      return { pageGroup: "resource", topic: topicFromText(text, "education") };
    }
    return { pageGroup: "other", topic: topicFromText(text, "general") };
  }

  function topicFromText(text, fallback) {
    if (/react[-\s]?instantsearch|instantsearch/.test(text)) return "instantsearch_implementation";
    if (/api|sdk|integration|implementation|developer/.test(text)) return "implementation";
    if (/pricing|cost|usage|rate|request|api call/.test(text)) return "pricing_and_usage";
    if (/fashion|retail|ecommerce|commerce|merchandising/.test(text)) return "commerce";
    if (/marketplace/.test(text)) return "marketplace";
    if (/ai search|neural|recommend|personalization|semantic/.test(text)) return "ai_search";
    if (/customer|case stud|roi|conversion|revenue/.test(text)) return "customer_proof";
    return fallback;
  }

  function productFocusFromText(text) {
    if (/personalization|personalized/.test(text)) {
      return { productFocus: "personalization", productFocusLabel: "Personalization" };
    }
    if (/recommend|recommendations/.test(text)) {
      return { productFocus: "recommendations", productFocusLabel: "AI Recommendations" };
    }
    if (/neural|semantic/.test(text)) {
      return { productFocus: "neural_search", productFocusLabel: "Neural Search" };
    }
    if (/instantsearch/.test(text)) {
      return { productFocus: "instantsearch", productFocusLabel: "InstantSearch" };
    }
    if (/ai search/.test(text)) {
      return { productFocus: "ai_search", productFocusLabel: "AI Search" };
    }
    if (/\/products\/search|site search|\bsearch\b/.test(text)) {
      return { productFocus: "search", productFocusLabel: "Search" };
    }
    return {};
  }

  function resetSessionForDemoIfRequested() {
    try {
      if (new URLSearchParams(location.search).get(RESET_QUERY_PARAM) !== "1") return;
      sessionStorage.removeItem(SESSION_KEY);
      sessionStorage.removeItem(EVENTS_KEY);
      sessionStorage.removeItem(PROACTIVE_STATE_KEY);
      session = null;
      currentPageId = null;
      debug("reset session-scoped proactive state from query parameter");
    } catch {
      // Demo reset is best effort and must never break the page.
    }
  }

  function initializeProfile() {
    const { token, source } = getUserToken();
    const profile = readProfile();
    const ts = Date.now();
    const nextProfile = {
      schema: PROFILE_SCHEMA,
      visitorId: profile.visitorId || id("visitor"),
      userToken: profile.userToken || token,
      tokenSource: profile.tokenSource || source,
      firstSeenAt: profile.firstSeenAt || ts,
      lastSeenAt: ts,
      visits: (profile.visits || 0) + 1,
      persona: profile.persona || null,
      traits: profile.traits && typeof profile.traits === "object" ? profile.traits : {},
    };
    writeProfile(nextProfile);
    return nextProfile;
  }

  function initializeSession() {
    const existing = readSession();
    const ts = Date.now();
    const expired =
      !existing?.sessionId || !existing?.lastSeenAt || ts - existing.lastSeenAt > SESSION_TTL_MS;

    const nextSession = expired
      ? {
          schema: SESSION_SCHEMA,
          sessionId: id("sess"),
          startedAt: ts,
          lastSeenAt: ts,
          currentPageId: null,
          pages: [],
          engagementHistory: [],
        }
      : {
          schema: SESSION_SCHEMA,
          sessionId: existing.sessionId,
          startedAt: existing.startedAt || ts,
          lastSeenAt: ts,
          currentPageId: existing.currentPageId || null,
          pages: Array.isArray(existing.pages) ? existing.pages : [],
          engagementHistory: Array.isArray(existing.engagementHistory)
            ? existing.engagementHistory
            : [],
        };

    writeSession(nextSession);

    const events = readEventsEnvelope();
    if (events.sessionId !== nextSession.sessionId) {
      writeEventsEnvelope({ schema: EVENTS_SCHEMA, sessionId: nextSession.sessionId, events: [] });
    }

    return nextSession;
  }

  function initializeState() {
    if (!isAllowed()) return;
    initializeProfile();
    initializeSession();
  }

  function currentPage() {
    return session?.pages?.find((page) => page.pageId === currentPageId) || null;
  }

  function upsertCurrentPage(overrides) {
    if (!session) initializeSession();

    const existingIndex = session.pages.findIndex((page) => page.pageId === currentPageId);
    const nextPage =
      existingIndex >= 0
        ? { ...session.pages[existingIndex], ...overrides }
        : { pageId: currentPageId || id("page"), ...overrides };

    if (!currentPageId) currentPageId = nextPage.pageId;
    nextPage.pageId = currentPageId;

    const pages = [...session.pages];
    if (existingIndex >= 0) pages[existingIndex] = nextPage;
    else pages.push(nextPage);

    writeSession({
      ...session,
      currentPageId,
      pages: pages.slice(-MAX_PAGES),
    });
    return nextPage;
  }

  function track(name, props) {
    if (!isAllowed()) return null;
    if (!session) initializeSession();

    const envelope = readEventsEnvelope();
    const event = {
      eventId: id("evt"),
      name,
      ts: Date.now(),
      isoTime: nowIso(),
      sessionId: session.sessionId,
      pageId: currentPageId,
      path: location.pathname,
      source: "observed",
      props: sanitizeProps(props),
    };

    envelope.events.push(event);
    writeEventsEnvelope(envelope);
    writeSession(session);
    debug("event", name, event.props);
    emitEngagementSignal(event);
    return event;
  }

  function emitEngagementSignal(event) {
    try {
      document.dispatchEvent(
        new CustomEvent("algolia-engagement-signal", {
          detail: {
            eventId: event.eventId,
            name: event.name,
            ts: event.ts,
            pageId: event.pageId,
            path: event.path,
            props: event.props,
          },
        })
      );
    } catch {
      // The storage write is the source of truth; visual listeners are best effort.
    }
  }

  function trackPageView() {
    if (!isAllowed()) return;
    flushPageDwell();

    currentPageId = id("page");
    currentPageStartedAt = Date.now();
    currentScrollMilestone = 0;

    const classification = pageClassification();
    const page = upsertCurrentPage({
      pageId: currentPageId,
      path: location.pathname,
      url: currentUrl(),
      title: truncate(document.title, 160),
      referrer: safeUrl(document.referrer),
      enteredAt: currentPageStartedAt,
      dwellMs: 0,
      maxScrollDepth: 0,
      pageGroup: classification.pageGroup,
      topic: classification.topic,
      productFocus: classification.productFocus,
      productFocusLabel: classification.productFocusLabel,
    });

    track("page_view", {
      url: page.url,
      title: page.title,
      referrer: page.referrer,
      pageGroup: page.pageGroup,
      topic: page.topic,
      productFocus: page.productFocus,
      productFocusLabel: page.productFocusLabel,
      utm: currentUtm(),
    });

    for (const milestone of DWELL_MILESTONES_MS) {
      setTimeout(() => {
        if (currentPageId !== page.pageId) return;
        updatePageDwell();
        track("page_dwell", {
          dwellSeconds: Math.round(milestone / 1000),
          pageGroup: page.pageGroup,
          topic: page.topic,
          productFocus: page.productFocus,
          productFocusLabel: page.productFocusLabel,
        });
      }, milestone);
    }
  }

  function updatePageDwell() {
    const page = currentPage();
    if (!page) return;
    upsertCurrentPage({ dwellMs: Date.now() - currentPageStartedAt });
  }

  function flushPageDwell() {
    if (!currentPageId) return;
    updatePageDwell();
  }

  function scrollPercent() {
    const bodyHeight = document.body?.scrollHeight || 0;
    const docHeight = document.documentElement?.scrollHeight || 0;
    const height = Math.max(1, bodyHeight, docHeight);
    return Math.min(100, Math.round(((window.scrollY + window.innerHeight) / height) * 100));
  }

  function handleScroll() {
    const percent = scrollPercent();
    for (const milestone of SCROLL_MILESTONES) {
      if (percent >= milestone && currentScrollMilestone < milestone) {
        currentScrollMilestone = milestone;
        const page = currentPage();
        upsertCurrentPage({ maxScrollDepth: milestone });
        track("scroll_depth", {
          depth: milestone,
          pageGroup: page?.pageGroup,
          topic: page?.topic,
          productFocus: page?.productFocus,
          productFocusLabel: page?.productFocusLabel,
        });
      }
    }
  }

  function closestElement(target, selector) {
    try {
      return target?.closest?.(selector) || null;
    } catch {
      return null;
    }
  }

  function elementLabel(element) {
    return (
      truncate(element?.getAttribute?.("aria-label")) ||
      truncate(element?.getAttribute?.("title")) ||
      truncate(element?.textContent)
    );
  }

  function isNavigationClick(anchor) {
    if (!anchor) return false;
    return !!closestElement(anchor, "nav, header, [role='navigation'], [data-nav]");
  }

  function classifyCta(anchor) {
    const href = anchor?.getAttribute?.("href") || "";
    const dataCta = anchor?.getAttribute?.("data-cta");
    if (dataCta) return dataCta;
    if (/demo|contact|sales/i.test(href)) return "demo_or_contact";
    if (/pricing/i.test(href)) return "pricing";
    if (/signup|start|trial/i.test(href)) return "trial_or_signup";
    if (/\/doc\/|\/docs|developer/i.test(href)) return "documentation";
    return null;
  }

  function handleClick(event) {
    const target = event.target;
    const anchor = closestElement(target, "a, button, [role='button'], [data-cta], [data-nav]");
    if (!anchor) return;

    const label = elementLabel(anchor);
    const href = safeHrefFromElement(anchor);

    if (isNavigationClick(anchor)) {
      track("nav_click", {
        label,
        href,
        navGroup: truncate(anchor.getAttribute?.("data-nav") || anchor.closest?.("[data-nav]")?.getAttribute?.("data-nav")),
      });
    }

    const ctaType = classifyCta(anchor);
    if (ctaType) {
      track("cta_click", {
        ctaType,
        label,
        href,
      });
    }

    if (closestElement(anchor, "[data-search-result], .ais-Hits, .ais-InfiniteHits")) {
      track("search_result_click", {
        label,
        href,
      });
    }
  }

  function searchInputSelector() {
    return [
      "input[type='search']",
      "input[aria-label*='search' i]",
      "input[placeholder*='search' i]",
      "[role='searchbox']",
    ].join(",");
  }

  function handleSearchEvent(event) {
    const input = closestElement(event.target, searchInputSelector());
    if (!input) return;
    if (event.type === "keydown" && event.key !== "Enter") return;
    const query = truncate(input.value || input.textContent, 120);
    if (!query) return;
    track("site_search", {
      query,
      trigger: event.type === "keydown" ? "enter" : event.type,
    });
  }

  function formId(form) {
    return (
      truncate(form?.getAttribute?.("data-form")) ||
      truncate(form?.getAttribute?.("id")) ||
      "form"
    );
  }

  function fieldCategory(element) {
    const type = element?.getAttribute?.("type") || element?.tagName || "field";
    return truncate(String(type).toLowerCase(), 40);
  }

  function handleFormFocus(event) {
    const form = closestElement(event.target, "form");
    if (!form || form.__algoliaEngagementStarted) return;
    if (!form.__algoliaEngagementViewed) {
      form.__algoliaEngagementViewed = true;
      track("form_view", { formId: formId(form) });
    }
    form.__algoliaEngagementStarted = true;
    track("form_start", { formId: formId(form), fieldCategory: fieldCategory(event.target) });
  }

  function handleFormSubmit(event) {
    const form = event.target;
    if (!form?.matches?.("form")) return;
    track("form_submit", { formId: formId(form) });
  }

  function handleFormInvalid(event) {
    const form = closestElement(event.target, "form");
    if (!form) return;
    track("form_error", {
      formId: formId(form),
      fieldCategory: fieldCategory(event.target),
      errorCategory: "validation",
    });
  }

  function recordEngagement(input) {
    if (!isAllowed()) return null;
    if (!session) initializeSession();

    const engagement = {
      id: id("eng"),
      pageId: currentPageId,
      messageGoal: truncate(input?.messageGoal || input?.goal || "concierge_engagement", 80),
      shownAt: Date.now(),
      status: truncate(input?.status || "shown", 60),
    };

    const engagementHistory = [...(session.engagementHistory || []), engagement].slice(
      -MAX_ENGAGEMENTS
    );
    writeSession({ ...session, engagementHistory });

    const eventName =
      engagement.status === "dismissed"
        ? "engagement_dismissed"
        : engagement.status === "clicked"
          ? "engagement_clicked"
          : "engagement_exposed";

    track(eventName, {
      engagementId: engagement.id,
      messageGoal: engagement.messageGoal,
      status: engagement.status,
    });

    return engagement;
  }

  function setPersona(personaId) {
    const value = truncate(personaId, 60);
    if (!value) return null;
    const profile = readProfile();
    const persona = {
      value,
      state: "confirmed",
      source: "demo_selector",
      updatedAt: Date.now(),
    };
    writeProfile({ ...profile, persona, lastSeenAt: Date.now() });
    return track("persona_select", { persona: value });
  }

  function identify(userToken) {
    const value = truncate(userToken, 160);
    if (!value) return;
    explicitUserToken = value;
    const profile = readProfile();
    writeProfile({
      ...profile,
      userToken: value,
      tokenSource: "override",
      lastSeenAt: Date.now(),
    });
    debug("identified");
  }

  function snapshot() {
    const profile = readProfile();
    const currentSession = readSession() || session || {};
    const eventsEnvelope = readEventsEnvelope();
    return {
      profile,
      session: currentSession,
      events: eventsEnvelope.events,
    };
  }

  function reset() {
    writeJson(localStorage, PROFILE_KEY, null);
    writeJson(sessionStorage, SESSION_KEY, null);
    writeJson(sessionStorage, EVENTS_KEY, null);
    try {
      sessionStorage.removeItem(TOKEN_KEY);
    } catch {
      // ignore
    }
    session = null;
    currentPageId = null;
    initializeState();
    trackPageView();
  }

  function registerWithChatWidget() {
    const source = {
      getProfile() {
        return readProfile();
      },
      getEvents() {
        return readEventsEnvelope().events.slice(-20);
      },
      getSessionPages() {
        return (readSession()?.pages || []).slice(-MAX_PAGES);
      },
      getSession() {
        return readSession() || {};
      },
      snapshot,
    };

    const widget = window.algoliaChat;
    if (typeof widget?.setVisitorDataSource === "function") {
      widget.setVisitorDataSource(source);
      debug("registered with window.algoliaChat");
    }

    const element = document.querySelector?.("algolia-chat");
    if (typeof element?.setVisitorDataSource === "function") {
      element.setVisitorDataSource(source);
      debug("registered with <algolia-chat>");
    }
  }

  function installRouteWatcher() {
    if (routeWatchInstalled) return;
    routeWatchInstalled = true;
    const originalPushState = history.pushState?.bind(history);
    if (originalPushState) {
      history.pushState = function (...args) {
        const result = originalPushState(...args);
        setTimeout(trackPageView, 0);
        return result;
      };
    }
    window.addEventListener("popstate", () => setTimeout(trackPageView, 0));
    window.addEventListener("beforeunload", flushPageDwell);
    document.addEventListener("visibilitychange", () => {
      if (document.hidden) flushPageDwell();
    });
  }

  function installClickWatcher() {
    if (clickWatchInstalled) return;
    clickWatchInstalled = true;
    document.addEventListener("click", handleClick, true);
    window.addEventListener("scroll", handleScroll, { passive: true });
  }

  function installSearchWatcher() {
    if (searchWatchInstalled) return;
    searchWatchInstalled = true;
    document.addEventListener("change", handleSearchEvent, true);
    document.addEventListener("keydown", handleSearchEvent, true);
  }

  function installFormWatcher() {
    if (formWatchInstalled) return;
    formWatchInstalled = true;
    document.addEventListener("focusin", handleFormFocus, true);
    document.addEventListener("submit", handleFormSubmit, true);
    document.addEventListener("invalid", handleFormInvalid, true);
  }

  function installChatWatcher() {
    if (chatWatchInstalled) return;
    chatWatchInstalled = true;
    document.addEventListener("algolia-chat-open-change", (event) => {
      track("chat_open", { open: !!event.detail?.open });
    });
    document.addEventListener("algolia-chat-question", (event) => {
      track("chat_question", { source: event.detail?.source || "chat" });
    });
    document.addEventListener("algolia-chat-engaged", (event) => {
      recordEngagement({
        messageGoal: event.detail?.messageGoal || "proactive_concierge",
        status: "shown",
      });
    });
    document.addEventListener("algolia-chat-engagement-dismissed", (event) => {
      recordEngagement({
        messageGoal: event.detail?.messageGoal || "proactive_concierge",
        status: "dismissed",
      });
    });
    document.addEventListener("algolia-chat-engagement-clicked", (event) => {
      recordEngagement({
        messageGoal: event.detail?.messageGoal || "proactive_concierge",
        status: "clicked",
      });
    });
    document.addEventListener("algolia-chat:lead", () => {
      track("form_success", { formId: "lead_form" });
    });
  }

  function processQueue(existingApi) {
    if (!Array.isArray(existingApi?._queue)) return;
    for (const item of existingApi._queue) {
      const [method, args = []] = Array.isArray(item) ? item : [];
      if (method === "configure") configure(...args);
      else if (method === "identify") identify(...args);
      else if (method === "setPersona") setPersona(...args);
      else if (method === "track" || method === "trackEvent") track(...args);
      else if (method === "recordEngagement") recordEngagement(...args);
      else if (method === "setConsentAdapter") setConsentAdapter(...args);
    }
  }

  function install() {
    const root = window;
    if (root.__algoliaEngagementTrackerInstalled) return;
    root.__algoliaEngagementTrackerInstalled = true;

    const previousEngagementApi = root.algoliaEngagementTracker;
    const previousLegacyApi = root.algoliaTracker;

    configure(readWindowConfig());
    initializeState();

    const api = {
      configure,
      identify,
      setPersona,
      track,
      trackEvent: track,
      recordEngagement,
      setConsentAdapter,
      refreshProfile: readProfile,
      snapshot,
      reset,
    };

    root.algoliaEngagementTracker = api;
    root.algoliaTracker = api;

    processQueue(previousEngagementApi);
    processQueue(previousLegacyApi);

    resetSessionForDemoIfRequested();
    trackPageView();
    installRouteWatcher();
    installClickWatcher();
    installSearchWatcher();
    installFormWatcher();
    installChatWatcher();
    registerWithChatWidget();
  }

  install();
})();

(function () {
  "use strict";

  const LABEL = "[Algolia Context Compiler]";
  const DEBUG =
    new URLSearchParams(location.search).get("algoliaChatDebug") === "1" ||
    new URLSearchParams(location.search).get("algoliaContextDebug") === "1";

  const PROFILE_KEY = "algolia_profile";
  const SESSION_KEY = "algolia_session";
  const EVENTS_KEY = "algolia_events";

  const PACKET_SCHEMA = "AlgoliaContextPacket.v1";
  const MAX_RECENT_EVENTS = 15;
  const MAX_TURN_CONTEXT_KEYS = 32;
  const MAX_TURN_CONTEXT_BYTES = 4096;
  const MAX_TURN_CONTEXT_VALUE_BYTES = 1024;
  const AGENT_STUDIO_COMPLETIONS_RE = /\/agent-studio\/1\/agents\/[^/]+\/completions/;
  const SENSITIVE_PROP_RE =
    /email|phone|password|passwd|token|secret|api[_-]?key|credential|name|company|value/i;
  const REDACT_EMAIL_RE = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;
  const REDACT_PHONE_RE = /\b(?:\+?\d[\d .()/-]{7,}\d)\b/g;

  let config = {
    autoInstallFetchInterceptor: true,
    maxRecentEvents: MAX_RECENT_EVENTS,
  };
  let originalFetch = null;
  let patchedFetch = null;

  function debugLog(...args) {
    if (DEBUG) console.log(LABEL, ...args);
  }

  function configure(nextConfig) {
    config = { ...config, ...(nextConfig || {}) };
  }

  function readJson(storage, key, fallback) {
    try {
      const raw = storage.getItem(key);
      return raw ? JSON.parse(raw) : fallback;
    } catch {
      return fallback;
    }
  }

  function rawSnapshot() {
    return {
      profile: readJson(localStorage, PROFILE_KEY, null),
      session: readJson(sessionStorage, SESSION_KEY, null),
      eventsEnvelope: readJson(sessionStorage, EVENTS_KEY, { events: [] }),
    };
  }

  function byteLength(value) {
    const text = String(value);
    try {
      return new TextEncoder().encode(text).length;
    } catch {
      return text.length;
    }
  }

  function clampText(value, maxLength = 180) {
    if (value === undefined || value === null) return undefined;
    const clean = String(value)
      .replace(REDACT_EMAIL_RE, "[redacted-email]")
      .replace(REDACT_PHONE_RE, "[redacted-phone]")
      .replace(/\s+/g, " ")
      .trim();
    if (!clean) return undefined;
    return clean.length > maxLength ? `${clean.slice(0, maxLength - 1)}...` : clean;
  }

  function sanitizeProps(props) {
    const clean = {};
    for (const [key, value] of Object.entries(props || {})) {
      if (SENSITIVE_PROP_RE.test(key)) continue;
      if (value === undefined || value === null) continue;
      if (typeof value === "string") clean[key] = clampText(value);
      else if (typeof value === "number" || typeof value === "boolean") clean[key] = value;
      else if (Array.isArray(value)) clean[key] = value.slice(0, 8).map((item) => clampText(item));
      else if (typeof value === "object") clean[key] = sanitizeProps(value);
    }
    return clean;
  }

  function currentPath() {
    try {
      return location.pathname || "/";
    } catch {
      return "/";
    }
  }

  function normalizeEvents(eventsEnvelope) {
    const events = Array.isArray(eventsEnvelope?.events) ? eventsEnvelope.events : [];
    return events
      .filter((event) => event && event.name !== "nav_hover" && event.name !== "hover")
      .map((event) => ({
        eventId: clampText(event.eventId, 80),
        name: clampText(event.name, 80),
        ts: Number.isFinite(event.ts) ? event.ts : 0,
        pageId: clampText(event.pageId, 80),
        path: clampText(event.path, 160),
        source: event.source === "inferred" ? "inferred" : "observed",
        props: sanitizeProps(event.props),
      }))
      .filter((event) => event.name)
      .sort((a, b) => a.ts - b.ts);
  }

  function classifyPath(path = currentPath(), title = "") {
    const text = `${path} ${title}`.toLowerCase();
    if (text.includes("/pricing")) return { pageGroup: "pricing", topic: "pricing_and_usage" };
    if (text.includes("/demo") || text.includes("contact-sales")) {
      return { pageGroup: "conversion", topic: "demo_request" };
    }
    if (text.includes("/customers")) return { pageGroup: "customer_story", topic: topicFromText(text, "customer_proof") };
    if (text.includes("/doc/") || text.includes("/docs") || text.includes("/api")) {
      return { pageGroup: "documentation", topic: topicFromText(text, "implementation") };
    }
    if (text.includes("/developers") || text.includes("/developer")) {
      return { pageGroup: "developer", topic: topicFromText(text, "developer_experience") };
    }
    if (text.includes("/products")) {
      return {
        pageGroup: "product",
        topic: topicFromText(text, "product_research"),
        ...productFocusFromText(text),
      };
    }
    if (text.includes("/industries") || text.includes("/solutions")) {
      return { pageGroup: "solution", topic: topicFromText(text, "industry_solution") };
    }
    if (text.includes("/blog") || text.includes("/resources")) return { pageGroup: "resource", topic: topicFromText(text, "education") };
    return { pageGroup: "other", topic: topicFromText(text, "general") };
  }

  function topicFromText(text, fallback) {
    if (/react[-\s]?instantsearch|instantsearch/.test(text)) return "instantsearch_implementation";
    if (/recommend|personalization|ai search|neural|semantic/.test(text)) return "ai_search";
    if (/api|sdk|integration|implementation|developer|doc/.test(text)) return "implementation";
    if (/pricing|cost|usage|rate|api call|request/.test(text)) return "pricing_and_usage";
    if (/fashion|retail|ecommerce|commerce|merchandising/.test(text)) return "commerce";
    if (/customer|case stud|roi|conversion|revenue/.test(text)) return "customer_proof";
    if (/marketplace/.test(text)) return "marketplace";
    return fallback;
  }

  function productFocusFromText(text) {
    if (/personalization|personalized/.test(text)) {
      return { productFocus: "personalization", productFocusLabel: "Personalization" };
    }
    if (/recommend|recommendations/.test(text)) {
      return { productFocus: "recommendations", productFocusLabel: "AI Recommendations" };
    }
    if (/neural|semantic/.test(text)) {
      return { productFocus: "neural_search", productFocusLabel: "Neural Search" };
    }
    if (/instantsearch/.test(text)) {
      return { productFocus: "instantsearch", productFocusLabel: "InstantSearch" };
    }
    if (/ai search/.test(text)) {
      return { productFocus: "ai_search", productFocusLabel: "AI Search" };
    }
    if (/\/products\/search|site search|\bsearch\b/.test(text)) {
      return { productFocus: "search", productFocusLabel: "Search" };
    }
    return {};
  }

  function pageWithClassification(page) {
    const classified = classifyPath(page?.path, page?.title);
    const merged = { ...classified, ...(page || {}) };
    if (!merged.productFocus && classified.productFocus) {
      merged.productFocus = classified.productFocus;
      merged.productFocusLabel = classified.productFocusLabel;
    }
    return merged;
  }

  function findCurrentPage(session) {
    const pages = Array.isArray(session?.pages) ? session.pages : [];
    return (
      pages.find((page) => page.pageId && page.pageId === session?.currentPageId) ||
      [...pages].reverse().find((page) => page.path === currentPath()) ||
      pages.at(-1) ||
      {
        pageId: null,
        path: currentPath(),
        title: typeof document !== "undefined" ? document.title : "",
        pageGroup: classifyPath().pageGroup,
        topic: classifyPath().topic,
      }
    );
  }

  function scoreFromSignals({ currentPage, recentEvents }) {
    const text = [
      currentPage?.path,
      currentPage?.title,
      currentPage?.pageGroup,
      currentPage?.topic,
      ...recentEvents.map((event) => [
        event.name,
        event.path,
        event.props?.label,
        event.props?.query,
        event.props?.topic,
        event.props?.pageGroup,
      ].filter(Boolean).join(" ")),
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();

    const recentNames = new Set(recentEvents.slice(-6).map((event) => event.name));
    const hasRecentDemoSignal =
      recentNames.has("cta_click") ||
      recentNames.has("form_attempt") ||
      recentNames.has("form_success") ||
      text.includes("contact sales") ||
      text.includes("demo");
    const currentPageGroup = currentPage?.pageGroup || classifyPath(currentPage?.path, currentPage?.title).pageGroup;
    const isCommercialPage = currentPageGroup === "pricing" || currentPageGroup === "conversion";

    if (/recommend|personalization|ai search|neural|semantic/.test(text) && !hasRecentDemoSignal && !isCommercialPage) {
      const pricingFriction = /pricing|cost|usage|api call|rate/.test(text);
      return {
        intent: {
          value: "ai_recommendations_evaluation",
          state: "inferred",
          confidence: 0.72,
          evidence: evidenceFor(recentEvents, currentPage, ["recommend", "personalization", "ai_search", "site_search", "nav_click"]),
        },
        friction: {
          value: pricingFriction ? "pricing_or_cost_unclear" : "fit_and_value_unclear",
          state: "inferred",
          confidence: pricingFriction ? 0.68 : 0.62,
          evidence: evidenceFor(recentEvents, currentPage, ["implementation", "api", "pricing", "cost", "site_search"]),
        },
        nextBestAction: {
          value: "explain_feature_fit_with_example",
          state: "inferred",
          confidence: 0.66,
        },
      };
    }

    if (hasRecentDemoSignal || isCommercialPage || /pricing|cost|usage|api call|rate/.test(text)) {
      return {
        intent: {
          value: "pricing_or_demo_evaluation",
          state: "inferred",
          confidence: 0.74,
          evidence: evidenceFor(recentEvents, currentPage, ["pricing", "cost", "demo", "cta_click", "site_search"]),
        },
        friction: {
          value: "pricing_or_cost_unclear",
          state: "inferred",
          confidence: 0.68,
          evidence: evidenceFor(recentEvents, currentPage, ["pricing", "cost", "api call", "rate", "site_search"]),
        },
        nextBestAction: {
          value: "answer_cost_or_route_to_demo",
          state: "inferred",
          confidence: 0.7,
        },
      };
    }

    if (/developer|implementation|instantsearch|api|sdk|doc/.test(text)) {
      return {
        intent: {
          value: "implementation_research",
          state: "inferred",
          confidence: 0.69,
          evidence: evidenceFor(recentEvents, currentPage, ["developer", "implementation", "instantsearch", "api", "sdk"]),
        },
        friction: {
          value: "development_effort_unclear",
          state: "inferred",
          confidence: 0.64,
          evidence: evidenceFor(recentEvents, currentPage, ["implementation", "api", "sdk", "doc"]),
        },
        nextBestAction: {
          value: "answer_implementation_path",
          state: "inferred",
          confidence: 0.66,
        },
      };
    }

    return {
      intent: {
        value: "general_algolia_research",
        state: "inferred",
        confidence: 0.45,
        evidence: evidenceFor(recentEvents, currentPage, []),
      },
      friction: {
        value: "question_behind_question_unknown",
        state: "inferred",
        confidence: 0.38,
        evidence: [],
      },
      nextBestAction: {
        value: "answer_then_ask_discovery_question",
        state: "inferred",
        confidence: 0.44,
      },
    };
  }

  function evidenceFor(events, currentPage, terms) {
    const evidence = [];
    const pageText = [currentPage?.title, currentPage?.path, currentPage?.topic].filter(Boolean).join(" ");
    if (pageText) evidence.push(`current_page:${clampText(pageText, 120)}`);
    const loweredTerms = terms.map((term) => term.toLowerCase());
    for (const event of [...events].reverse()) {
      const eventText = JSON.stringify({ name: event.name, path: event.path, props: event.props }).toLowerCase();
      if (!loweredTerms.length || loweredTerms.some((term) => eventText.includes(term))) {
        evidence.push(`${event.name}:${clampText(event.props?.label || event.props?.query || event.path, 120)}`);
      }
      if (evidence.length >= 4) break;
    }
    return evidence;
  }

  function inferPersona(profile, recentEvents, currentPage) {
    const confirmed = profile?.persona;
    if (confirmed?.value) {
      return {
        value: clampText(confirmed.value, 60),
        state: confirmed.state === "confirmed" ? "confirmed" : "observed",
        source: clampText(confirmed.source || "profile", 80),
      };
    }

    const text = [
      currentPage?.path,
      currentPage?.title,
      currentPage?.pageGroup,
      currentPage?.topic,
      ...recentEvents.map((event) => JSON.stringify({ name: event.name, props: event.props })),
    ].join(" ").toLowerCase();

    if (/developer|doc|api|sdk|implementation|instantsearch/.test(text)) {
      return { value: "developer", state: "inferred", confidence: 0.66, source: "behavior" };
    }
    if (/pricing|roi|customer|case stud|executive|value/.test(text)) {
      return { value: "executive", state: "inferred", confidence: 0.58, source: "behavior" };
    }
    if (/fashion|retail|merchandising|recommend|personalization|commerce/.test(text)) {
      return { value: "merchandiser", state: "inferred", confidence: 0.56, source: "behavior" };
    }
    return { value: "unknown", state: "unknown", confidence: 0, source: "insufficient_signal" };
  }

  function summarizeEvents(events) {
    const counts = {};
    for (const event of events) counts[event.name] = (counts[event.name] || 0) + 1;
    return counts;
  }

  function compile() {
    const raw = rawSnapshot();
    const profile = raw.profile || {};
    const session = raw.session || {};
    const events = normalizeEvents(raw.eventsEnvelope);
    const maxRecentEvents = Number.isFinite(config.maxRecentEvents)
      ? config.maxRecentEvents
      : MAX_RECENT_EVENTS;
    const recentEvents = events.slice(-maxRecentEvents);
    const currentPage = findCurrentPage(session);
    const classifiedPage = pageWithClassification(currentPage);
    const persona = inferPersona(profile, recentEvents, classifiedPage);
    const inferences = scoreFromSignals({ currentPage: classifiedPage, recentEvents });

    return {
      schema: PACKET_SCHEMA,
      compiledAt: Date.now(),
      profile: {
        visitorId: clampText(profile.visitorId, 80),
        visits: Number.isFinite(profile.visits) ? profile.visits : undefined,
        persona,
      },
      session: {
        sessionId: clampText(session.sessionId, 80),
        startedAt: session.startedAt,
        pageCount: Array.isArray(session.pages) ? session.pages.length : 0,
        engagementHistory: Array.isArray(session.engagementHistory)
          ? session.engagementHistory.slice(-5).map((item) => ({
              id: clampText(item.id, 80),
              messageGoal: clampText(item.messageGoal, 100),
              shownAt: item.shownAt,
              status: clampText(item.status, 80),
            }))
          : [],
      },
      currentPage: {
        pageId: clampText(classifiedPage.pageId, 80),
        path: clampText(classifiedPage.path || currentPath(), 160),
        title: clampText(classifiedPage.title, 160),
        pageGroup: clampText(classifiedPage.pageGroup, 80),
        topic: clampText(classifiedPage.topic, 80),
        productFocus: clampText(classifiedPage.productFocus, 80),
        productFocusLabel: clampText(classifiedPage.productFocusLabel, 80),
        dwellMs: Number.isFinite(classifiedPage.dwellMs) ? classifiedPage.dwellMs : 0,
        maxScrollDepth: Number.isFinite(classifiedPage.maxScrollDepth) ? classifiedPage.maxScrollDepth : 0,
      },
      observedSignals: {
        currentTopic: {
          value: clampText(classifiedPage.topic || "general", 80),
          state: "observed",
          source: "current_page",
        },
        currentProductFocus: classifiedPage.productFocus
          ? {
              value: clampText(classifiedPage.productFocus, 80),
              label: clampText(classifiedPage.productFocusLabel, 80),
              state: "observed",
              source: "current_page",
            }
          : undefined,
        eventCounts: summarizeEvents(events),
      },
      recentEvents,
      inferences: {
        persona,
        ...inferences,
      },
    };
  }

  function inferenceValue(signal) {
    if (!signal?.value) return undefined;
    if (signal.state === "inferred") {
      const confidence = Number.isFinite(signal.confidence)
        ? Math.round(signal.confidence * 100) / 100
        : 0;
      return `inferred:${signal.value}:${confidence}`;
    }
    return `${signal.state || "observed"}:${signal.value}`;
  }

  function compileTurnContext() {
    const packet = compile();
    const recentEventSummary = packet.recentEvents
      .slice(-8)
      .map((event) => `${event.name}:${event.props?.label || event.props?.query || event.path || ""}`)
      .join(" | ");
    const priorEngagements = packet.session.engagementHistory
      .map((item) => `${item.messageGoal}:${item.status}`)
      .join(" | ");

    const context = {
      context_schema: "AlgoliaTurnContext.v1",
      persona: inferenceValue(packet.profile.persona),
      current_page: packet.currentPage.path,
      current_page_group: packet.currentPage.pageGroup,
      current_topic: inferenceValue(packet.observedSignals.currentTopic),
      current_product_focus: inferenceValue(packet.observedSignals.currentProductFocus),
      current_product_focus_label: packet.currentPage.productFocusLabel,
      current_dwell_seconds: String(Math.round((packet.currentPage.dwellMs || 0) / 1000)),
      current_scroll_depth: String(packet.currentPage.maxScrollDepth || 0),
      session_page_count: String(packet.session.pageCount || 0),
      recent_events: recentEventSummary,
      prior_engagements: priorEngagements || undefined,
      intent: inferenceValue(packet.inferences.intent),
      friction: inferenceValue(packet.inferences.friction),
      next_best_action: inferenceValue(packet.inferences.nextBestAction),
      instruction:
        "Use confirmed/observed context as context, phrase inferred context softly, never expose telemetry.",
    };

    return enforceTurnContextLimits(context);
  }

  function enforceTurnContextLimits(input) {
    const output = {};
    for (const [key, value] of Object.entries(input)) {
      if (!/^[a-zA-Z0-9_.-]{1,64}$/.test(key)) continue;
      if (value === undefined || value === null) continue;
      let text = clampText(String(value), 1000);
      if (!text) continue;
      while (byteLength(text) > MAX_TURN_CONTEXT_VALUE_BYTES) {
        text = text.slice(0, Math.max(1, text.length - 20));
      }
      output[key] = text;
      if (Object.keys(output).length >= MAX_TURN_CONTEXT_KEYS) break;
      if (byteLength(JSON.stringify(output)) > MAX_TURN_CONTEXT_BYTES) {
        delete output[key];
        break;
      }
    }
    return output;
  }

  function isAgentStudioCompletion(url) {
    try {
      const text = typeof url === "string" ? url : url?.url || "";
      return AGENT_STUDIO_COMPLETIONS_RE.test(text);
    } catch {
      return false;
    }
  }

  function injectTurnContextIntoBody(body) {
    if (typeof body !== "string") return body;
    let payload;
    try {
      payload = JSON.parse(body);
    } catch {
      return body;
    }
    if (!Array.isArray(payload.messages)) return body;

    const index = [...payload.messages].map((message, i) => ({ message, i }))
      .reverse()
      .find(({ message }) => message?.role === "user")?.i;
    if (index === undefined) return body;

    const turnContext = compileTurnContext();
    payload.messages[index] = {
      ...payload.messages[index],
      metadata: {
        ...(payload.messages[index].metadata || {}),
        turnContext: {
          ...(payload.messages[index].metadata?.turnContext || {}),
          ...turnContext,
        },
      },
    };
    debugLog("injected turnContext", turnContext);
    return JSON.stringify(payload);
  }

  function installFetchInterceptor() {
    if (typeof window.fetch !== "function") return false;
    if (patchedFetch && window.fetch === patchedFetch) return false;
    originalFetch = window.fetch;
    patchedFetch = function algoliaContextFetch(input, init = {}) {
      if (!isAgentStudioCompletion(input)) {
        return originalFetch.apply(this, arguments);
      }
      const nextInit = { ...(init || {}) };
      nextInit.body = injectTurnContextIntoBody(nextInit.body);
      return originalFetch.call(this, input, nextInit);
    };
    window.fetch = patchedFetch;
    return true;
  }

  function uninstallFetchInterceptor() {
    if (!originalFetch || !patchedFetch) return false;
    window.fetch = originalFetch;
    originalFetch = null;
    patchedFetch = null;
    return true;
  }

  function debug() {
    const raw = rawSnapshot();
    const compiled = compile();
    const turnContext = compileTurnContext();
    const result = { raw, compiled, turnContext };
    debugLog("debug", result);
    return result;
  }

  const api = {
    configure,
    compile,
    compileTurnContext,
    debug,
    installFetchInterceptor,
    uninstallFetchInterceptor,
    _injectTurnContextIntoBody: injectTurnContextIntoBody,
  };

  window.algoliaContextCompiler = api;

  if (config.autoInstallFetchInterceptor) {
    installFetchInterceptor();
  }
})();

(function () {
