        currentTopic: {
          value: clampText(classifiedPage.topic || "general", 80),
          state: "observed",
          source: "current_page",
        },
        currentProductFocus: classifiedPage.productFocus
          ? {
              value: clampText(classifiedPage.productFocus, 80),
              label: clampText(classifiedPage.productFocusLabel, 80),
              state: "observed",
              source: "current_page",
