      return raw ? JSON.parse(raw) : fallback;
    } catch {
      return fallback;
    }
  }

  function writeJson(key, value) {
    try {
      sessionStorage.setItem(key, JSON.stringify(value));
    } catch {
      // Proactive state should never break the host page.
    }
  }

  function readState() {
    const value = readJson(STATE_KEY, null);
    return {
      schema: STATE_SCHEMA,
      opportunities: Array.isArray(value?.opportunities) ? value.opportunities : [],
      lastOpportunityAt: Number.isFinite(value?.lastOpportunityAt) ? value.lastOpportunityAt : 0,
    };
  }

  function writeState(state) {
    writeJson(STATE_KEY, {
      schema: STATE_SCHEMA,
      opportunities: state.opportunities.slice(-20),
      lastOpportunityAt: state.lastOpportunityAt || 0,
    });
  }

  function updateOpportunity(opportunityId, patch) {
    const state = readState();
    const index = state.opportunities.findIndex((item) => item.id === opportunityId);
    if (index === -1) return false;
    state.opportunities[index] = {
      ...state.opportunities[index],
      ...patch,
      updatedAt: Date.now(),
    };
    writeState(state);
    return true;
  }

  function compilerPacket() {
    const compiler = window.algoliaContextCompiler;
    if (!compiler || typeof compiler.compile !== "function") return null;
    return compiler.compile();
  }

  function compilerTurnContext() {
    const compiler = window.algoliaContextCompiler;
    if (!compiler || typeof compiler.compileTurnContext !== "function") return {};
    return compiler.compileTurnContext();
  }

  function currentPage(packet) {
    return packet?.currentPage || {};
  }

  function sessionPages(packet) {
    return Array.isArray(packet?.session?.pages)
      ? packet.session.pages
      : readJson("algolia_session", {}, sessionStorage).pages || [];
  }

  function recentEvents(packet) {
    return Array.isArray(packet?.recentEvents) ? packet.recentEvents : [];
  }

  function pageGroup(page) {
    return String(page?.pageGroup || "").toLowerCase();
  }

  function topic(page) {
    return String(page?.topic || "").toLowerCase();
  }

  function isProduct(page) {
    return pageGroup(page) === "product" || String(page?.path || "").includes("/products");
  }

  function isDeveloper(page) {
    const group = pageGroup(page);
    const path = String(page?.path || "");
    return group === "developer" || group === "documentation" || path.includes("/developers") || path.includes("/doc/");
  }

  function isPricing(page) {
    const group = pageGroup(page);
    const path = String(page?.path || "");
    return group === "pricing" || group === "conversion" || path.includes("/pricing") || path.includes("/demo") || path.includes("contact-sales");
  }

  function isCustomerStory(page) {
    return pageGroup(page) === "customer_story" || String(page?.path || "").includes("/customers/");
  }

  function hasRecentEvent(events, name) {
    return events.some((event) => event.name === name);
  }

  function chatElement() {
    return document.querySelector("algolia-chat");
  }

  function credentials() {
    const search = document.querySelector("algolia-instant-search");
    const legacyEngageConfig =
      window.ALGOLIA_CONTEXT_ENGINE_CONFIG && typeof window.ALGOLIA_CONTEXT_ENGINE_CONFIG === "object"
        ? window.ALGOLIA_CONTEXT_ENGINE_CONFIG
        : {};
    return {
      appId: config.appId || search?.getAttribute?.("app-id") || null,
      apiKey: config.apiKey || config.searchKey || search?.getAttribute?.("api-key") || null,
      greetingsAgentId:
        config.greetingsAgentId ||
        config.greetingAgentId ||
        legacyEngageConfig.greetingsAgentId ||
        legacyEngageConfig.greetingAgentId ||
        legacyEngageConfig.conciergeAgentId ||
        null,
    };
  }

  function agentCompletionUrl(agentId, appId) {
    const params = new URLSearchParams({
      compatibilityMode: config.compatibilityMode || COMPLETIONS_COMPATIBILITY_MODE,
      cache: String(config.cache === true),
      memory: String(config.memory === true),
    });
    return `https://${appId}.algolia.net/agent-studio/1/agents/${agentId}/completions?${params.toString()}`;
  }

  function hasSearchWithTerms(events, terms) {
    return events.some((event) => {
      if (event.name !== "site_search") return false;
      const query = JSON.stringify(event.props || {}).toLowerCase();
      return terms.some((term) => query.includes(term));
    });
  }

  function priorPage(pages, predicate) {
    return [...pages].slice(0, -1).reverse().find(predicate) || null;
  }

  function countPages(pages, predicate) {
    return pages.filter(predicate).length;
  }

  function productFocus(page) {
    const value = String(page?.productFocus || "").trim();
    if (!value) return null;
    return {
      value,
      label: String(page?.productFocusLabel || value).trim(),
      state: "observed",
      source: isProduct(page) ? "current_product_page" : "prior_product_page",
      pagePath: page?.path || null,
      pageTitle: page?.title || null,
    };
  }

  function contextualFocusFor(packet) {
    const page = currentPage(packet);
    const currentFocus = productFocus(page);
    if (currentFocus) return currentFocus;
    const priorProduct = priorPage(sessionPages(packet), isProduct);
    const priorFocus = productFocus(priorProduct);
    return priorFocus ? { ...priorFocus, source: "prior_product_page" } : null;
  }

  function baseDecision(packet, fields) {
    const page = currentPage(packet);
    const events = recentEvents(packet);
    return {
      schema: SCHEMA,
      engage: true,
      createdAt: Date.now(),
      pageId: page.pageId || null,
      pagePath: page.path || location.pathname,
      source: "browser_deterministic",
      reasonCodes: [],
      agentPromptPacket: {
        schema: GREETING_REQUEST_SCHEMA,
        moment: fields.moment,
        trigger: fields.trigger,
        priority: fields.priority,
        persona: packet?.profile?.persona || null,
        currentPage: page,
        contextualFocus: contextualFocusFor(packet),
        journey: sessionPages(packet).map((item) => ({
          path: item.path,
          title: item.title,
          pageGroup: item.pageGroup,
          topic: item.topic,
          productFocus: item.productFocus,
          productFocusLabel: item.productFocusLabel,
          dwellMs: item.dwellMs,
          maxScrollDepth: item.maxScrollDepth,
        })),
        observedSignals: events.map((event) => ({
          name: event.name,
          path: event.path,
          props: event.props,
        })),
        inferredIntent: packet?.inferences?.intent || null,
        friction: packet?.inferences?.friction || null,
        messageGoal: fields.messageGoal,
        source: "browser_deterministic",
        tone: "sharp, useful, warm, lightly witty",
        constraints: {
          maxWords: 34,
          noTelemetryExposure: true,
          includeQuestionChips: true,
        },
      },
      ...fields,
    };
  }

  function withReasons(decision, reasonCodes) {
    return {
      ...decision,
      reasonCodes,
      agentPromptPacket: {
        ...decision.agentPromptPacket,
        reasonCodes,
      },
    };
  }

  function candidates(packet) {
    const page = currentPage(packet);
    const pages = sessionPages(packet);
    const events = recentEvents(packet);
    const result = [];
    const previousProduct = priorPage(pages, isProduct);
    const previousDeveloper = priorPage(pages, isDeveloper);
    const previousPricing = priorPage(pages, isPricing);

    if (isPricing(page) && previousProduct) {
      result.push(
        withReasons(
          baseDecision(packet, {
            moment: "commercial_evaluation",
            trigger: "product_to_pricing",
            priority: 88,
            messageGoal: "explain_cost_drivers",
          }),
          ["journey_product_to_pricing", "pricing_page_view"]
        )
      );
    }

    if (isPricing(page) && previousDeveloper) {
      result.push(
        withReasons(
          baseDecision(packet, {
            moment: "commercial_evaluation",
            trigger: "implementation_to_pricing",
            priority: 86,
            messageGoal: "connect_implementation_effort_to_cost",
          }),
          ["journey_implementation_to_pricing", "pricing_page_view"]
        )
      );
    }

    if (isDeveloper(page) && previousPricing) {
      result.push(
        withReasons(
          baseDecision(packet, {
            moment: "implementation_research",
            trigger: "pricing_to_implementation",
            priority: 84,
            messageGoal: "reduce_implementation_uncertainty",
          }),
          ["journey_pricing_to_implementation", "developer_page_view"]
        )
      );
    }

    if (isCustomerStory(page) && previousProduct) {
      result.push(
        withReasons(
          baseDecision(packet, {
            moment: "customer_proof",
            trigger: "product_to_customer_story",
            priority: 82,
            messageGoal: "surface_relevant_customer_proof",
          }),
          ["journey_product_to_customer_story", "customer_story_page"]
        )
      );
    }

    if (isDeveloper(page) && hasSearchWithTerms(events, ["api", "sdk", "react", "instantsearch", "implementation", "integrat"])) {
      result.push(
        withReasons(
          baseDecision(packet, {
            moment: "implementation_research",
            trigger: "search_to_docs",
            priority: 80,
            messageGoal: "answer_implementation_path",
          }),
          ["site_search_implementation_terms", "developer_page_view"]
        )
      );
    }

    if (isPricing(page) && Number(page.dwellMs || 0) >= config.pricingDwellMs) {
      result.push(
        withReasons(
          baseDecision(packet, {
            moment: "commercial_evaluation",
            trigger: "pricing_8s_dwell",
            priority: 78,
            messageGoal: "explain_cost_drivers",
          }),
          ["pricing_page", "pricing_dwell"]
        )
      );
    }

    if (isDeveloper(page) && Number(page.dwellMs || 0) >= config.implementationDwellMs) {
      result.push(
        withReasons(
          baseDecision(packet, {
            moment: "implementation_research",
            trigger: "developer_page_15s_dwell",
            priority: 76,
            messageGoal: "reduce_implementation_uncertainty",
          }),
          ["developer_page", "implementation_dwell"]
        )
      );
    }

    if (isDeveloper(page) && Number(page.maxScrollDepth || 0) >= config.implementationScrollDepth) {
      result.push(
        withReasons(
          baseDecision(packet, {
            moment: "implementation_research",
            trigger: "developer_page_60_scroll",
            priority: 74,
            messageGoal: "reduce_implementation_uncertainty",
          }),
          ["developer_page", "implementation_scroll"]
        )
      );
    }

    if (isCustomerStory(page) && Number(page.dwellMs || 0) >= config.customerProofDwellMs) {
      result.push(
        withReasons(
          baseDecision(packet, {
            moment: "customer_proof",
            trigger: "customer_story_12s_dwell",
            priority: 72,
            messageGoal: "surface_relevant_customer_proof",
          }),
          ["customer_story_page", "customer_story_dwell"]
        )
      );
    }

    if (isCustomerStory(page) && Number(page.maxScrollDepth || 0) >= config.customerProofScrollDepth) {
      result.push(
        withReasons(
          baseDecision(packet, {
            moment: "customer_proof",
            trigger: "customer_story_60_scroll",
            priority: 70,
            messageGoal: "surface_relevant_customer_proof",
          }),
          ["customer_story_page", "customer_story_scroll"]
        )
      );
    }

    if (isProduct(page) && Number(page.dwellMs || 0) >= config.productDwellMs) {
      result.push(
        withReasons(
          baseDecision(packet, {
            moment: "product_research",
            trigger: "product_page_10s_dwell",
            priority: 66,
            messageGoal: "explain_product_fit",
          }),
          ["product_page", "product_dwell"]
        )
      );
    }

    if (isProduct(page) && Number(page.maxScrollDepth || 0) >= config.productScrollDepth) {
      result.push(
        withReasons(
          baseDecision(packet, {
            moment: "product_research",
            trigger: "product_page_50_scroll",
            priority: 64,
            messageGoal: "explain_product_fit",
          }),
          ["product_page", "product_scroll"]
        )
      );
    }

    if (isProduct(page) && countPages(pages, isProduct) >= 2) {
      result.push(
        withReasons(
          baseDecision(packet, {
            moment: "journey_shift",
            trigger: "multiple_product_pages",
            priority: 62,
            messageGoal: "help_compare_capabilities",
          }),
          ["multiple_product_pages"]
        )
      );
    }

    return result.sort((left, right) => right.priority - left.priority);
  }

  function suppressionReason(packet, decision, state) {
    if (!config.enabled) return "disabled";
    if (!packet) return "missing_context_packet";
    if (!decision) return "no_trigger_match";
    if (hasRecentEvent(recentEvents(packet), "chat_open")) return "chat_already_open";
    if (document.hidden) return "page_hidden";
    const widget = document.querySelector("algolia-chat");
    if (widget && widget.autoEngage === false) return "auto_engage_disabled";
    if (state.opportunities.length >= config.maxOpportunitiesPerSession) return "session_cap_reached";
    if (Date.now() - state.lastOpportunityAt < config.cooldownMs) return "cooldown_active";
    const duplicate = state.opportunities.some(
      (item) =>
        item.pageId === decision.pageId &&
        item.moment === decision.moment &&
        item.status !== "expired"
    );
    if (duplicate) return "already_eligible_for_page_moment";
    return null;
  }

  function empty(reason) {
    return {
      schema: SCHEMA,
      engage: false,
      reason,
      createdAt: Date.now(),
    };
  }

  function updateDebugStatus(message, detail) {
    if (!DEBUG) return;
    const status = {
      message,
      detail,
      at: Date.now(),
    };
    window.__algoliaProactiveLastStatus = status;
    try {
      if (!document.body || typeof document.createElement !== "function") return;
      let node = document.getElementById?.("algolia-proactive-debug-status");
      if (!node) {
        node = document.createElement("div");
        node.id = "algolia-proactive-debug-status";
        node.setAttribute("style", [
          "position:fixed",
          "left:12px",
          "bottom:12px",
          "z-index:2147483647",
          "max-width:420px",
          "padding:8px 10px",
          "border:1px solid #3157ff",
          "border-radius:8px",
          "background:#fff",
          "color:#1f2a44",
          "font:12px/1.35 system-ui,-apple-system,BlinkMacSystemFont,sans-serif",
          "box-shadow:0 8px 24px rgba(31,42,68,.18)",
        ].join(";"));
        document.body.appendChild(node);
      }
      node.textContent = message;
      node.title = JSON.stringify(detail || {}).slice(0, 900);
    } catch {
      // Debug UI is best effort; the window/event state above is the testable source.
    }
  }

  function recordSuppression(decision) {
    if (!DEBUG) return;
    window.__algoliaProactiveLastSuppression = {
      reason: decision?.reason || "unknown",
      pagePath: decision?.pagePath || location.pathname,
      createdAt: Date.now(),
      decision,
    };
    updateDebugStatus(`Proactive suppressed: ${decision?.reason || "unknown"}`, decision);
    try {
      document.dispatchEvent(
        new CustomEvent("algolia-proactive-suppressed", {
          detail: window.__algoliaProactiveLastSuppression,
        })
      );
    } catch {
      // ignore
    }
  }

  function evaluate({ reserve = false } = {}) {
    const packet = compilerPacket();
    const state = readState();
    const decision = candidates(packet)[0] || null;
    const reason = suppressionReason(packet, decision, state);
    if (reason) return empty(reason);
    if (!reserve) return decision;

    const opportunityId = `opp_${Date.now().toString(16)}_${Math.random().toString(16).slice(2, 8)}`;
    const requestPacket = {
      ...decision.agentPromptPacket,
      schema: GREETING_REQUEST_SCHEMA,
      opportunityId,
      createdAt: Date.now(),
      moment: decision.moment,
      trigger: decision.trigger,
      priority: decision.priority,
      messageGoal: decision.messageGoal,
      reasonCodes: decision.reasonCodes,
    };
    const opportunity = {
      id: opportunityId,
      status: "eligible",
      pageId: decision.pageId,
      pagePath: decision.pagePath,
      moment: decision.moment,
      trigger: decision.trigger,
      priority: decision.priority,
      messageGoal: decision.messageGoal,
      reasonCodes: decision.reasonCodes,
      createdAt: Date.now(),
      requestPacket,
    };
    state.opportunities.push(opportunity);
    state.lastOpportunityAt = opportunity.createdAt;
    writeState(state);
    return {
      ...decision,
      opportunityId: opportunity.id,
      agentPromptPacket: requestPacket,
    };
  }

  function textFromSse(raw) {
    if (!String(raw || "").includes("data:")) return raw;
    let text = "";
    for (const line of String(raw).split("\n")) {
      const trimmed = line.trim();
      if (!trimmed.startsWith("data:")) continue;
      const payload = trimmed.slice(5).trim();
      if (!payload || payload === "[DONE]") continue;
      try {
        const event = JSON.parse(payload);
        if (event.type === "text-delta" && typeof event.delta === "string") text += event.delta;
        else if (event.type === "text" && typeof event.text === "string") text += event.text;
      } catch {
        // Non-JSON SSE data is ignored; we only trust structured text deltas.
      }
    }
    return text || raw;
  }

  function extractJsonObject(raw) {
    const text = textFromSse(raw);
    if (!text) return null;
    try {
      return JSON.parse(text);
    } catch {
      const start = text.indexOf("{");
      const end = text.lastIndexOf("}");
      if (start === -1 || end === -1 || end <= start) return null;
      try {
        return JSON.parse(text.slice(start, end + 1));
      } catch {
        return null;
      }
    }
  }

  function wordCount(text) {
    return String(text || "").trim().split(/\s+/).filter(Boolean).length;
  }

  function sameHandoffSummary(response, decision) {
    const summary = response?.handoffSummary || {};
    return (
      summary.moment === decision.moment &&
      summary.trigger === decision.trigger &&
      summary.messageGoal === decision.messageGoal
    );
  }

  function validateGreetingResponse(response, decision) {
    if (!response || typeof response !== "object") return "invalid_json";
    if (response.schema !== GREETING_RESPONSE_SCHEMA) return "invalid_schema";
    if (response.opportunityId !== decision.opportunityId) return "opportunity_mismatch";
    if (!sameHandoffSummary(response, decision)) return "handoff_summary_mismatch";

    const greeting = typeof response.greeting === "string" ? response.greeting.trim() : "";
    const greetingWords = wordCount(greeting);
    if (greetingWords < 12 || greetingWords > 34) return "invalid_greeting_length";
    if (BANNED_GREETING_RE.test(greeting)) return "telemetry_exposure";
    if (UNSUPPORTED_CLAIM_RE.test(greeting)) return "unsupported_claim";

    const chips = Array.isArray(response.chips) ? response.chips : [];
    if (chips.length > 3) return "too_many_chips";
    for (const chip of chips) {
      if (typeof chip !== "string" || !chip.trim()) return "invalid_chip";
      if (wordCount(chip) > 8) return "chip_too_long";
      if (BANNED_GREETING_RE.test(chip) || UNSUPPORTED_CLAIM_RE.test(chip)) return "invalid_chip";
    }
    return null;
  }

  function renderGreeting(response, decision) {
    const widget = chatElement();
    if (!widget || typeof widget.engage !== "function") {
      updateOpportunity(decision.opportunityId, { status: "widget_unavailable" });
      return false;
    }
    const chips = Array.isArray(response.chips)
      ? response.chips.map((chip) => chip.trim()).filter(Boolean)
      : [];
    const shown = widget.engage({
      greeting: response.greeting.trim(),
      suggestions: chips,
    });
    updateOpportunity(decision.opportunityId, {
      status: shown ? "shown" : "render_refused",
      shownAt: shown ? Date.now() : undefined,
      greetingResponse: {
        schema: GREETING_RESPONSE_SCHEMA,
        opportunityId: response.opportunityId,
        greeting: response.greeting.trim(),
        chips,
        handoffSummary: response.handoffSummary,
      },
    });
    return !!shown;
  }

  async function requestGreeting(decision) {
    const { appId, apiKey, greetingsAgentId } = credentials();
    if (!appId || !apiKey || !greetingsAgentId || typeof fetch !== "function") {
      debug("greetings agent not configured; emitted opportunity only");
      return false;
    }

    updateOpportunity(decision.opportunityId, { status: "greeting_requested" });
    const body = {
      id: `alg_cnv_proactive_${decision.opportunityId}`,
      messages: [
        {
          id: `alg_msg_proactive_${decision.opportunityId}`,
          role: "user",
          parts: [
            {
              type: "text",
              text: `PROACTIVE_GREETING_REQUEST\n${JSON.stringify(decision.agentPromptPacket)}`,
            },
          ],
          metadata: {
            turnContext: compilerTurnContext(),
          },
        },
      ],
    };

    try {
      const response = await fetch(agentCompletionUrl(greetingsAgentId, appId), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-Algolia-Application-Id": appId,
          "X-Algolia-API-Key": apiKey,
        },
        body: JSON.stringify(body),
      });
      if (!response.ok) {
        updateOpportunity(decision.opportunityId, {
          status: "greeting_failed",
          failureReason: `http_${response.status}`,
        });
        return false;
      }

      const parsed = extractJsonObject(await response.text());
      const validationError = validateGreetingResponse(parsed, decision);
      if (validationError) {
        updateOpportunity(decision.opportunityId, {
          status: "greeting_rejected",
          failureReason: validationError,
          rejectedGreetingResponse: parsed || null,
        });
        return false;
      }

      return renderGreeting(parsed, decision);
    } catch (error) {
      updateOpportunity(decision.opportunityId, {
        status: "greeting_failed",
        failureReason: error instanceof Error ? error.message : String(error),
      });
      return false;
    }
  }

  async function handleSignal(event) {
    const name = event?.detail?.name;
    if (!name || name === "nav_hover" || name === "hover") return;

    const decision = evaluate({ reserve: true });
    if (!decision.engage) {
      debug("no proactive opportunity", decision.reason);
      recordSuppression(decision);
      return;
    }

    debug("proactive opportunity", decision);
    updateDebugStatus(`Proactive opportunity: ${decision.trigger}`, decision);
    document.dispatchEvent(
      new CustomEvent("algolia-proactive-opportunity", {
        detail: decision,
      })
    );
    await requestGreeting(decision);
  }

  function scheduleInitialEvaluation() {
    const { appId, apiKey, greetingsAgentId } = credentials();
    if (!appId || !apiKey || !greetingsAgentId) return;
    setTimeout(() => {
      handleSignal({ detail: { name: "controller_ready" } });
    }, 0);
  }

  function debugState() {
    return {
      config,
      state: readState(),
      packet: compilerPacket(),
      decision: evaluate(),
    };
  }

  const root = window;
  if (!root.__algoliaProactiveControllerInstalled) {
    root.__algoliaProactiveControllerInstalled = true;
    const previous = root.ALGOLIA_PROACTIVE_CONFIG;
    if (previous && typeof previous === "object") configure(previous);
    document.addEventListener("algolia-engagement-signal", handleSignal);
    scheduleInitialEvaluation();
  }

  root.algoliaProactiveController = {
    configure,
    evaluate,
    debug: debugState,
  };
})();

(function () {
  "use strict";

  const LABEL = "[Algolia Handoff To Orchestrator]";
  const DEBUG =
    new URLSearchParams(location.search).get("algoliaChatDebug") === "1" ||
    new URLSearchParams(location.search).get("algoliaHandoffDebug") === "1";

  const STATE_KEY = "algolia_proactive_state";
  const HANDOFF_SCHEMA = "ProactiveHandoffContext.v1";
  const TOOL_INPUT_SCHEMA = "ProactiveHandoffToolInput.v1";
  const TOOL_NAME = "handoff_to_orchestrator";
  const AGENT_STUDIO_RE = /\/agent-studio\/1\/agents\/([^/?#]+)\/completions/;
  const DISCOVERY_CONTROL_RE = /\n*\[DISCOVERY CONTROL[^\]]*\][\s\S]*?\[END DISCOVERY CONTROL\]\s*/gi;
  const DISCOVERY_STATE_COMMENT_RE = /\n*<!--DISCOVERY_STATE[\s\S]*?DISCOVERY_STATE-->\s*/gi;

  let originalFetch = null;
  let patchedFetch = null;
  let config = {
    enabled: true,
    primaryAgentId: null,
    maxPacketChars: 6500,
  };

  function debug(...args) {
    if (DEBUG) console.log(LABEL, ...args);
  }

  function configure(nextConfig) {
    config = { ...config, ...(nextConfig || {}) };
    debug("configured", config);
  }

  function readJson(storage, key, fallback) {
    try {
      const raw = storage.getItem(key);
      return raw ? JSON.parse(raw) : fallback;
    } catch {
      return fallback;
    }
  }

  function writeJson(storage, key, value) {
    try {
      storage.setItem(key, JSON.stringify(value));
      return true;
    } catch {
      return false;
    }
  }

  function readState() {
    const state = readJson(sessionStorage, STATE_KEY, null);
    return {
      schema: "AlgoliaProactiveState.v1",
      opportunities: Array.isArray(state?.opportunities) ? state.opportunities : [],
      lastOpportunityAt: Number.isFinite(state?.lastOpportunityAt) ? state.lastOpportunityAt : 0,
    };
  }

  function writeState(state) {
    return writeJson(sessionStorage, STATE_KEY, {
      schema: state.schema || "AlgoliaProactiveState.v1",
      opportunities: state.opportunities.slice(-20),
      lastOpportunityAt: state.lastOpportunityAt || 0,
    });
  }

  function updateOpportunity(opportunityId, patch) {
    const state = readState();
    const index = state.opportunities.findIndex((item) => item.id === opportunityId);
    if (index === -1) return false;
    state.opportunities[index] = {
      ...state.opportunities[index],
      ...patch,
      updatedAt: Date.now(),
    };
    return writeState(state);
  }

  function primaryAgentId() {
    if (config.primaryAgentId) return config.primaryAgentId;
    const primary = document.querySelector('algolia-agent[role="primary"]');
    return primary?.getAttribute?.("agent-id") || null;
  }

  function agentIdFromUrl(input) {
    const url = typeof input === "string" ? input : input?.url || "";
    const match = AGENT_STUDIO_RE.exec(url);
    return match ? match[1] : null;
  }

  function latestShownOpportunity() {
    const state = readState();
    return [...state.opportunities]
      .reverse()
      .find((item) => item?.status === "shown" && item?.greetingResponse?.schema === "ProactiveGreetingResponse.v1");
  }

  function compilerPacket() {
    const compiler = window.algoliaContextCompiler;
    if (!compiler || typeof compiler.compile !== "function") return null;
    try {
      return compiler.compile();
    } catch {
      return null;
    }
  }

  function compilerTurnContext() {
    const compiler = window.algoliaContextCompiler;
    if (!compiler || typeof compiler.compileTurnContext !== "function") return {};
    try {
      return compiler.compileTurnContext();
    } catch {
      return {};
    }
  }

  function userTextFromPayload(payload) {
    const index = lastUserMessageIndex(payload);
    if (index === -1) return "";
    const part = payload.messages[index]?.parts?.find((item) => item?.type === "text" && typeof item.text === "string");
    return cleanVisitorText(part?.text || "");
  }

  function cleanVisitorText(text) {
    return String(text || "")
      .replace(DISCOVERY_CONTROL_RE, "")
      .replace(DISCOVERY_STATE_COMMENT_RE, "")
      .trim();
  }

  function lastUserMessageIndex(payload) {
    if (!Array.isArray(payload?.messages)) return -1;
    for (let index = payload.messages.length - 1; index >= 0; index -= 1) {
      if (payload.messages[index]?.role === "user") return index;
    }
    return -1;
  }

  function selectedChip(response, userResponse) {
    const text = String(userResponse || "").trim();
    const chips = Array.isArray(response?.chips) ? response.chips : [];
    return chips.find((chip) => chip === text) || null;
  }

  function clippedJson(value) {
    const text = JSON.stringify(value);
    const max = Number.isFinite(config.maxPacketChars) ? config.maxPacketChars : 6500;
    if (text.length <= max) return value;
    return {
      schema: value.schema,
      clipped: true,
      opportunityId: value.opportunityId,
      userResponse: value.userResponse,
      selectedChip: value.selectedChip,
      greeting: value.greeting,
      chips: value.chips,
      handoffSummary: value.handoffSummary,
      contextPacket: value.contextPacket
        ? {
            schema: value.contextPacket.schema,
            profile: value.contextPacket.profile,
            currentPage: value.contextPacket.currentPage,
            inferences: value.contextPacket.inferences,
          }
        : null,
    };
  }

  function buildHandoffPacket(opportunity, userResponse) {
    const response = opportunity.greetingResponse || {};
    const packet = {
      schema: HANDOFF_SCHEMA,
      opportunityId: opportunity.id,
      capturedAt: Date.now(),
      userResponse: String(userResponse || "").trim(),
      selectedChip: selectedChip(response, userResponse),
      greeting: response.greeting || "",
      chips: Array.isArray(response.chips) ? response.chips : [],
      handoffSummary: response.handoffSummary || null,
      requestPacket: opportunity.requestPacket || null,
      contextPacket: compilerPacket(),
      instruction:
        "This was a proactive engagement. Use the context softly, never expose telemetry, answer the user's response directly, then continue normal discovery.",
    };
    return clippedJson(packet);
  }

  function decorateBody(body) {
    if (!config.enabled || typeof body !== "string") return body;
    let payload;
    try {
      payload = JSON.parse(body);
    } catch {
      return body;
    }

    const opportunity = latestShownOpportunity();
    if (!opportunity) return body;

    const index = lastUserMessageIndex(payload);
    if (index === -1) return body;
    const parts = Array.isArray(payload.messages[index].parts) ? payload.messages[index].parts : [];
    const textPart = parts.find((part) => part?.type === "text" && typeof part.text === "string");
    if (!textPart || textPart.text.includes("PROACTIVE_HANDOFF_CONTEXT")) return body;

    const userResponse = userTextFromPayload(payload).trim();
    if (!userResponse) return body;

    const handoff = buildHandoffPacket(opportunity, userResponse);
    textPart.text = `${textPart.text}\n\nPROACTIVE_HANDOFF_CONTEXT\n${JSON.stringify(handoff)}`;
    payload.messages[index] = {
      ...payload.messages[index],
      metadata: {
        ...(payload.messages[index].metadata || {}),
        turnContext: {
          ...(payload.messages[index].metadata?.turnContext || {}),
          ...compilerTurnContext(),
        },
      },
    };

    updateOpportunity(opportunity.id, {
      status: "handoff_sent",
      handoffAt: Date.now(),
      userResponse,
      selectedChip: handoff.selectedChip,
      handoffSchema: HANDOFF_SCHEMA,
    });
    document.dispatchEvent(
      new CustomEvent("algolia-proactive-handoff", {
        bubbles: true,
        composed: true,
        detail: handoff,
      })
    );
    debug("attached proactive handoff", handoff);
    return JSON.stringify(payload);
  }

  async function handleHandoffTool(input = {}) {
    if (input.schema && input.schema !== TOOL_INPUT_SCHEMA) {
      return { success: false, error: { code: "INVALID_SCHEMA", message: "Invalid handoff tool schema." } };
    }
    const opportunityId = String(input.opportunityId || "").trim();
    if (!opportunityId) {
      return { success: false, error: { code: "MISSING_OPPORTUNITY", message: "Missing opportunityId." } };
    }
    const state = readState();
    const opportunity = state.opportunities.find((item) => item.id === opportunityId);
    if (!opportunity) {
      return { success: false, error: { code: "NOT_FOUND", message: "No matching proactive opportunity." } };
    }
    updateOpportunity(opportunityId, {
      status: "handoff_tool_called",
      toolCalledAt: Date.now(),
      greeting: input.greeting || opportunity.greetingResponse?.greeting || "",
      chips: Array.isArray(input.chips) ? input.chips : opportunity.greetingResponse?.chips || [],
      selectedChip: input.selectedChip || null,
      userResponse: input.userResponse || "",
    });
    return {
      success: true,
      opportunityId,
      message: "Handoff captured. The next orchestrator turn will receive the proactive context.",
    };
  }

  function installFetchInterceptor() {
    if (typeof window.fetch !== "function") return false;
    if (patchedFetch && window.fetch === patchedFetch) return false;
    originalFetch = window.fetch;
    patchedFetch = function algoliaHandoffFetch(input, init = {}) {
      const targetAgentId = agentIdFromUrl(input);
      const primary = primaryAgentId();
      if (targetAgentId && primary && targetAgentId === primary && init && typeof init.body === "string") {
        const nextInit = { ...(init || {}), body: decorateBody(init.body) };
        return originalFetch.call(this, input, nextInit);
      }
      return originalFetch.apply(this, arguments);
    };
    window.fetch = patchedFetch;
    return true;
  }

  function waitForToolRegistry() {
    const register = () => {
      if (!window.algoliaChat || typeof window.algoliaChat.registerTool !== "function") return false;
      window.algoliaChat.registerTool(TOOL_NAME, handleHandoffTool);
      debug(`registered tool '${TOOL_NAME}'`);
      return true;
    };
    if (register()) return;
    const interval = setInterval(() => {
      if (register()) clearInterval(interval);
    }, 100);
    setTimeout(() => clearInterval(interval), 15000);
  }

  if (!window.__algoliaHandoffToOrchestratorInstalled) {
    window.__algoliaHandoffToOrchestratorInstalled = true;
    if (window.ALGOLIA_HANDOFF_CONFIG && typeof window.ALGOLIA_HANDOFF_CONFIG === "object") {
      configure(window.ALGOLIA_HANDOFF_CONFIG);
    }
    installFetchInterceptor();
    waitForToolRegistry();
  }

  window.algoliaHandoffToOrchestrator = {
    configure,
    decorateBody,
    buildHandoffPacket,
    handleHandoffTool,
    installFetchInterceptor,
  };
})();

(function () {
  "use strict";

  const LABEL = "[Algolia Chat – Engage]";
  const DEBUG = new URLSearchParams(location.search).get("algoliaChatDebug") === "1";

  const PROFILE_KEY = "algolia_profile";
  const EVENTS_KEY = "algolia_events";
  const SESSION_KEY = "algolia_session";
  const PENDING_GREETING_KEY = "algolia_pending_greeting";

  const DEFAULT_GREETING_TTL_MS = 600 * 1000;
  const DEFAULT_SIGNAL_PULSE_MS = 900;
  const DEFAULT_SIGNAL_DEBOUNCE_MS = 700;
  const DEFAULT_MIN_ANALYSIS_INTERVAL_MS = 5000;

  let config = {
    minPages: 2,
    minEvents: 3,
    analysisDelayMs: 3000,
    widgetTimeoutMs: 25000,
    greetingTtlMs: DEFAULT_GREETING_TTL_MS,
    signalPulseMs: DEFAULT_SIGNAL_PULSE_MS,
    signalDebounceMs: DEFAULT_SIGNAL_DEBOUNCE_MS,
    minAnalysisIntervalMs: DEFAULT_MIN_ANALYSIS_INTERVAL_MS,
    enableProactiveAnalysis: false,
  };

  let engaged = false;
  let analysisInFlight = false;
  let signalAnalysisTimer = null;
  let signalPulseTimer = null;
  let lastAnalysisAt = 0;

  function debug(...args) {
    if (DEBUG) console.log(LABEL, ...args);
  }

  function readWindowConfig() {
    try {
      const value = window.ALGOLIA_CONTEXT_ENGINE_CONFIG;
      return value && typeof value === "object" ? value : {};
    } catch {
      return {};
    }
  }

  function parseNumber(value) {
    if (!value) return undefined;
    const number = Number(value);
    return Number.isFinite(number) ? number : undefined;
  }

  function readQueryConfig() {
    try {
      const params = new URLSearchParams(location.search);
      const next = {};
      const conciergeAgentId = params.get("concierge") ?? params.get("conciergeAgentId");
      if (conciergeAgentId) next.conciergeAgentId = conciergeAgentId;

      const minPages = parseNumber(params.get("minPages"));
      if (minPages !== undefined) next.minPages = minPages;

      const minEvents = parseNumber(params.get("minEvents"));
      if (minEvents !== undefined) next.minEvents = minEvents;

      const analysisDelayMs = parseNumber(params.get("delayMs") ?? params.get("analysisDelayMs"));
      if (analysisDelayMs !== undefined) next.analysisDelayMs = analysisDelayMs;

      return next;
    } catch {
      return {};
    }
  }

  function configure(nextConfig) {
    config = { ...config, ...(nextConfig || {}) };
    debug("configured", config);
  }

  function readJson(key, fallback, storage = localStorage) {
    try {
      const value = storage.getItem(key);
      return value ? JSON.parse(value) : fallback;
    } catch {
      return fallback;
    }
  }

  function writeJson(key, value) {
    try {
      if (value === null) localStorage.removeItem(key);
      else localStorage.setItem(key, JSON.stringify(value));
    } catch {
      // Best effort only; pending greetings should never break the host page.
    }
  }

  function buildContext() {
    const profile = readJson(PROFILE_KEY, {});
    const session = readJson(SESSION_KEY, {}, sessionStorage);
    const eventEnvelope = readJson(EVENTS_KEY, {}, sessionStorage);
    const pages = Array.isArray(session.pages) ? session.pages : [];
    const events = Array.isArray(eventEnvelope)
      ? eventEnvelope
      : Array.isArray(eventEnvelope.events)
        ? eventEnvelope.events
        : [];

    const context = {
      currentPage: { path: location.pathname, title: document.title },
      pagesViewed: pages.map((page) => ({
        path: page.path,
        title: page.title,
        dwellMs: page.dwellMs,
      })),
      pageCount: pages.length,
      sessionDurationMs: session.startedAt ? Date.now() - session.startedAt : 0,
      events: events.slice(-15),
      affinities: Array.isArray(profile.topAffinities) ? profile.topAffinities : [],
      affinitySource: profile.tokenSource || "none",
    };

    return config.enrichContext ? config.enrichContext(context) : context;
  }

  function hasEnoughSignals(context) {
    const { minPages = 2, minEvents = 3 } = config;
    if (context.pageCount === 0 && context.events.length === 0) {
      debug("no visitor data — is algolia-engagement-tracker.js installed?");
      return false;
    }

    const enough = context.pageCount >= minPages || context.events.length >= minEvents;
    debug(
      `signal check → ${enough ? "ENOUGH" : "not enough"} | pages=${context.pageCount} (min ${minPages}) events=${context.events.length}`
    );
    return enough;
  }

  function chatElement() {
    return document.querySelector("algolia-chat");
  }

  function setAnalyzing(value) {
    chatElement()?.setAnalyzing?.(value);
  }

  function waitForWidget(timeoutMs) {
    const current = chatElement();
    if (current && typeof current.engage === "function") return Promise.resolve(true);

    return new Promise((resolve) => {
      const deadline = Date.now() + timeoutMs;
      const interval = setInterval(() => {
        const next = chatElement();
        if (next && typeof next.engage === "function") {
          clearInterval(interval);
          resolve(true);
        } else if (Date.now() > deadline) {
          clearInterval(interval);
          resolve(false);
        }
      }, 250);
    });
  }

  function parseSseTextDelta(line) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("data:")) return "";
    const payload = trimmed.slice(5).trim();
    if (!payload) return "";

    try {
      const event = JSON.parse(payload);
      return event.type === "text-delta" && typeof event.delta === "string" ? event.delta : "";
    } catch {
      return "";
    }
  }

  async function readSseText(stream) {
    const reader = stream.getReader();
    const decoder = new TextDecoder();
    let buffer = "";
    let text = "";

    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split("\n");
      buffer = lines.pop() ?? "";
      for (const line of lines) text += parseSseTextDelta(line);
    }

    return text;
  }

  function credentials() {
    const search = document.querySelector("algolia-instant-search");
    return {
      appId: config.appId ?? search?.getAttribute("app-id") ?? null,
      apiKey: config.apiKey ?? search?.getAttribute("api-key") ?? null,
    };
  }

  async function callConcierge(prompt) {
    const { appId, apiKey } = credentials();
    if (!appId || !apiKey) throw new Error("no Algolia credentials found on the page");

    const agentId = config.conciergeAgentId;
    if (!agentId) throw new Error("no conciergeAgentId configured");

    const url = `https://${appId}.algolia.net/agent-studio/1/agents/${agentId}/completions?compatibilityMode=ai-sdk-5`;
    const response = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Algolia-Application-Id": appId,
        "X-Algolia-API-Key": apiKey,
      },
      body: JSON.stringify({
        messages: [{ role: "user", parts: [{ type: "text", text: prompt }] }],
      }),
    });

    if (!response.ok) throw new Error(`concierge call failed: ${response.status}`);
    return readSseText(response.body);
  }

  function extractJsonObject(text) {
    const start = text.indexOf("{");
    const end = text.lastIndexOf("}");
    if (start === -1 || end === -1) return null;

    try {
      return JSON.parse(text.slice(start, end + 1));
    } catch {
      return null;
    }
  }

  function showPendingGreeting() {
    const pending = readJson(PENDING_GREETING_KEY, null);
    if (!pending) return false;

    const ttlMs = config.greetingTtlMs ?? DEFAULT_GREETING_TTL_MS;
    if (Date.now() - pending.ts > ttlMs) {
      writeJson(PENDING_GREETING_KEY, null);
      return false;
    }

    writeJson(PENDING_GREETING_KEY, null);
    debug("showing greeting cached by previous page");
    return showGreeting(pending.greeting, pending.suggestions ?? []);
  }

  function showGreeting(greeting, suggestions) {
    const widget = chatElement();
    if (!widget || typeof widget.engage !== "function") return false;

    const shown = widget.engage({ greeting, suggestions });
    engaged = !!shown;
    debug(shown ? "engaged" : "engage() refused — auto-engage is off");
    return engaged;
  }

  function canAnalyze(context) {
    if (engaged) {
      debug("already engaged on this page");
      return false;
    }

    const widget = chatElement();
    if (!widget) {
      debug("no <algolia-chat> on the page");
      return false;
    }

    if (widget.autoEngage === false) {
      debug("visitor switched auto-engage off");
      return false;
    }

    const ttlMs = config.greetingTtlMs ?? DEFAULT_GREETING_TTL_MS;
    const pending = readJson(PENDING_GREETING_KEY, null);
    if (pending && Date.now() - pending.ts < ttlMs) {
      debug("greeting already pending");
      return false;
    }

    if (!config.conciergeAgentId) {
      console.warn(
        LABEL,
        'no conciergeAgentId — the chat stays click-to-open. Set <algolia-chat-engage concierge-agent-id="...">'
      );
      return false;
    }

    return hasEnoughSignals(context);
  }

  function applyDecision(decision) {
    if (!decision?.engage) {
      debug("concierge decided not to engage", decision ?? "(unparseable response)");
      setAnalyzing(false);
      return;
    }

    const greeting = (typeof decision.greeting === "string" ? decision.greeting : "").trim();
    if (!greeting) {
      debug("engage:true but empty greeting — ignoring");
      setAnalyzing(false);
      return;
    }

    const suggestions = Array.isArray(decision.suggestions)
      ? decision.suggestions.filter((suggestion) => typeof suggestion === "string" && !!suggestion.trim())
      : [];

    if (document.hidden) {
      debug("page hidden — caching greeting for next page");
      writeJson(PENDING_GREETING_KEY, { greeting, suggestions, ts: Date.now() });
      setAnalyzing(false);
      return;
    }

    showGreeting(greeting, suggestions);
  }

  async function analyze() {
    const context = buildContext();
    if (!canAnalyze(context)) return;

    debug("calling concierge with context", context);
    analysisInFlight = true;
    lastAnalysisAt = Date.now();
    setAnalyzing(true);

    try {
      const raw = await callConcierge(`CONTEXT:\n${JSON.stringify(context, null, 2)}`);
      debug("concierge raw response:", raw.slice(0, 500));
      applyDecision(extractJsonObject(raw));
    } catch (error) {
      console.warn(LABEL, "proactive analysis failed:", error instanceof Error ? error.message : error);
      setAnalyzing(false);
    } finally {
      analysisInFlight = false;
    }
  }

  function pulseLauncher() {
    const widget = chatElement();
    if (!widget || widget.autoEngage === false || engaged) return;

    setAnalyzing(true);
    if (signalPulseTimer !== null) clearTimeout(signalPulseTimer);
    signalPulseTimer = setTimeout(() => {
      signalPulseTimer = null;
      if (!analysisInFlight) setAnalyzing(false);
    }, config.signalPulseMs ?? DEFAULT_SIGNAL_PULSE_MS);
  }

  function scheduleSignalAnalysis() {
    if (engaged || analysisInFlight) return;

    const minIntervalMs = config.minAnalysisIntervalMs ?? DEFAULT_MIN_ANALYSIS_INTERVAL_MS;
    if (Date.now() - lastAnalysisAt < minIntervalMs) return;

    if (signalAnalysisTimer !== null) clearTimeout(signalAnalysisTimer);
    signalAnalysisTimer = setTimeout(() => {
      signalAnalysisTimer = null;
      analyze().catch((error) => {
        console.warn(LABEL, "signal analysis failed:", error instanceof Error ? error.message : error);
        setAnalyzing(false);
      });
    }, config.signalDebounceMs ?? DEFAULT_SIGNAL_DEBOUNCE_MS);
  }

  function handleEngagementSignal(event) {
    const name = event?.detail?.name;
    if (!name) return;

    pulseLauncher();
    if (config.enableProactiveAnalysis) scheduleSignalAnalysis();
  }

  async function init() {
    const { widgetTimeoutMs = 25000, analysisDelayMs = 3000 } = config;
    if (!(await waitForWidget(widgetTimeoutMs))) {
      debug(`<algolia-chat> never became ready within ${widgetTimeoutMs}ms`);
      return;
    }

    if (config.enableProactiveAnalysis && !showPendingGreeting()) {
      await new Promise((resolve) => setTimeout(resolve, analysisDelayMs));
      await analyze();
    }
  }

  const root = window;
  if (!root.__algoliaChat_engageInstalled) {
    root.__algoliaChat_engageInstalled = true;
    configure(readQueryConfig());
    configure(readWindowConfig());

    const previous = root.algoliaEngage;
    root.algoliaEngage = { configure };
    if (Array.isArray(previous?._queue)) {
      for (const [nextConfig] of previous._queue) configure(nextConfig);
    }

    document.addEventListener("algolia-engagement-signal", handleEngagementSignal);
    init().catch((error) => {
      console.warn(LABEL, "init failed:", error instanceof Error ? error.message : error);
    });
  }
})();
